#!/usr/bin/env Rscript
args<-grep('^--file=',commandArgs(FALSE),value=TRUE)[1];here<-dirname(normalizePath(sub('^--file=','',args)))
suppressPackageStartupMessages({library(ggplot2);library(cowplot);library(svglite)})
cowplot::set_null_device('agg');navy<-'#315778';gold<-'#93640B';ink<-'#202B37'
e<-read.csv(file.path(here,'plot_estimates.csv'));s<-read.csv(file.path(here,'summary.csv'))
th<-function()theme_classic(base_size=10,base_family='Arial')+theme(text=element_text(colour=ink),axis.text=element_text(size=9,colour=ink),axis.line=element_line(linewidth=.28),axis.ticks=element_line(linewidth=.28),legend.title=element_blank(),legend.position='bottom',legend.text=element_text(size=8),legend.key.width=grid::unit(7,'mm'),plot.margin=margin(17,8,8,17))
xs<-scale_x_continuous(trans='log10',breaks=c(100,500,2000),labels=c('100','500','2,000'));xl<-'Independent labels / class'
means<-function(k){d<-subset(e,contrast==k);d$method<-factor(d$method,levels=c('raw','point'),labels=c('Observed','Corrected'));d$model<-factor(d$model,levels=c('control','directed'),labels=c('Reversible','Asymmetric')); truth<-if(k=='triple').05 else .06
 ggplot(d,aes(ncal,mean,colour=method,linetype=model,shape=model,group=interaction(method,model)))+geom_hline(yintercept=c(0,truth),colour=ink,linewidth=.25,linetype='dotted')+geom_line(linewidth=.65)+geom_errorbar(aes(ymin=lo,ymax=hi),width=.05,linewidth=.35)+geom_point(size=1.7)+scale_colour_manual(values=c(Observed=navy,Corrected=gold))+scale_linetype_manual(values=c(Reversible='dashed',Asymmetric='solid'))+scale_shape_manual(values=c(Reversible=1,Asymmetric=16))+xs+labs(x=xl,y=if(k=='triple')'Mean triple contrast' else 'Mean lag-two contrast')+th()+theme(legend.position='none')+annotate('text',x=110,y=if(k=='triple') .058 else .070,label='Observed',hjust=0,colour=navy,family='Arial',size=2.7)+annotate('text',x=110,y=if(k=='triple') .052 else .062,label='Corrected',hjust=0,colour=gold,family='Arial',size=2.7)}
cover<-function(m){d<-subset(s,model==m & method!='oracle');d$method<-factor(d$method,levels=c('fixed','joint'),labels=c('Fixed matrix','Joint uncertainty'));d$contrast<-factor(d$contrast,levels=c('triple','lag2'),labels=c('Triple','Lag 2'))
 ggplot(d,aes(ncal,coverage,colour=method,linetype=contrast,shape=contrast,group=interaction(method,contrast)))+geom_hline(yintercept=.95,colour=ink,linewidth=.3,linetype='dotted')+geom_line(linewidth=.65)+geom_errorbar(aes(ymin=coverage_lo,ymax=coverage_hi),width=.05,linewidth=.35)+geom_point(size=1.6)+scale_colour_manual(values=c('Fixed matrix'=navy,'Joint uncertainty'=gold))+scale_linetype_manual(values=c(Triple='solid','Lag 2'='dashed'))+scale_shape_manual(values=c(Triple=16,'Lag 2'=1))+xs+scale_y_continuous(limits=c(.65,1),breaks=c(.7,.8,.9,1))+labs(x=xl,y='Coverage of nominal 95% interval')+th()+theme(legend.position='none')+annotate('text',x=110,y=.72,label='Fixed matrix',hjust=0,colour=navy,family='Arial',size=2.7)+annotate('text',x=110,y=.68,label='Joint uncertainty',hjust=0,colour=gold,family='Arial',size=2.7)}
a<-means('lag2');b<-means('triple');c<-cover('control');d<-cover('directed')
g<-ggdraw(plot_grid(a,b,c,d,ncol=2));for(k in 1:4)g<-g+draw_label(c('a','b','c','d')[k],x=c(.008,.508,.008,.508)[k],y=c(.992,.992,.492,.492)[k],hjust=0,vjust=1,fontfamily='Arial',fontface='bold',size=12)
for(ext in c('pdf','svg','eps','png')){f<-file.path(here,paste0('Figure_calibration.',ext));if(ext=='pdf')ggsave(f,g,width=7.1,height=6.4,device=cairo_pdf,bg='white')else if(ext=='svg')ggsave(f,g,width=7.1,height=6.4,device=svglite,bg='white')else if(ext=='eps')ggsave(f,g,width=7.1,height=6.4,device=cairo_ps,onefile=FALSE,bg='white')else ggsave(f,g,width=7.1,height=6.4,dpi=300,bg='white')}
